<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/db.php'; $adminUser=requireAdmin(); $adminPageTitle='Patients / Users';
$users=$adminConnection->query("SELECT u.id,u.name,u.email,u.account_status,u.created_at,COUNT(a.id) AS booking_count FROM users u LEFT JOIN appointments a ON a.user_id=u.id WHERE u.role='patient' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll(); require __DIR__ . '/includes/header.php';
?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>User ID</th><th>Name</th><th>Email</th><th>Bookings</th><th>Status</th><th>Registered</th><th>Action</th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><?= (int)$user['id'] ?></td><td><?= htmlspecialchars($user['name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($user['email'],ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$user['booking_count'] ?></td><td><span class="admin-status admin-status-<?= strtolower($user['account_status']) ?>"><?= htmlspecialchars($user['account_status'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars($user['created_at'],ENT_QUOTES,'UTF-8') ?></td><td><form method="post" action="actions/update_user.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="user_id" value="<?= (int)$user['id'] ?>"><input type="hidden" name="status" value="<?= $user['account_status']==='Active'?'Inactive':'Active' ?>"><button class="admin-btn admin-btn-secondary" type="submit"><?= $user['account_status']==='Active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$users): ?><p class="admin-empty">No patient accounts found.</p><?php endif; ?></div><?php require __DIR__ . '/includes/footer.php'; ?>
